  'billing.schools.title': 'Schools by plan',
  'billing.schools.how': 'Each night just after midnight in India, a school past its paid-until day goes into grace for the days its plan gives, then becomes read-only. Recording a payment opens it again. A school with no paid-until day is not billed yet and is never touched.',
