  'billing.pay.open': 'Record a payment',
  'billing.pay.title': 'Record a payment',
  'billing.pay.how': 'For a payment you received outside the app: by cheque, UPI or bank transfer. It moves the paid-until day forward. Once a school is paid up to today, it gets full access again if the billing check had held it back or it was in a grace period set by hand. A school paused or made read-only by hand stays as it is. An entry is never edited afterwards.',
