  // Control → Messaging & Cost by month (docs/26 slice 8f, C205).
  'cost.month.purpose': 'WhatsApp message cost by school for a month.',
  'cost.month.about': 'What each live school’s WhatsApp messages cost in a month of India’s calendar, from the send-gate’s own records, beside the school’s limit.',
  'cost.month.counts': 'For {month}, by India’s calendar: spend is what delivered, billable messages cost with GST, at the price recorded when each was sent; on its way is sent but not yet confirmed delivered, and is not spend; counted against the limit is what the send-gate adds up before it lets a message go, which is spend and the priced messages sent but not yet confirmed delivered; held back by the limit is what that check stopped, or what a school with no limit could not send; held, rate not verified is a real account’s message whose category had no rate in force; attempts is every message logged, whatever became of it.',
  'cost.month.month': 'Month',
  'cost.month.thisMonth': 'this month',
  'cost.month.show': 'Show month',
  'cost.month.earlier': 'Earlier month',
  'cost.month.later': 'Later month',
  'cost.month.export': 'Download this list (CSV)',
  'cost.month.flagged.title': 'At, over or near the limit, or held back by it',
  'cost.month.flagged.none': 'In {month} no school reached its limit, came near it, or had a message held back by it.',
  'cost.month.flagged.line': 'Counted against the limit: {counted} of {limit}. Held back by the limit: {held}.',
  'cost.month.flagged.rule': 'A school is judged on what is counted against its limit, not on spend alone. Near the limit: four fifths of it or more is counted. Limit held messages back: less than all of it is counted, but the send-gate held a message that would have passed it, since the limit was last set. At or over the limit: all of it is counted, and nothing more is sent.',
  'cost.month.limitThen': 'For a month that is over, the limit shown is the one in force at the end of that month, read from the limit changes kept in the audit log. Where no change is on record, it is the limit set now.',
  'cost.month.list.title': 'Each live school in {month}',
  'cost.month.list.none.title': 'No live school yet',
  'cost.month.list.none.do': 'When a school goes live it is listed here with its month, even before it sends a message. Nothing is needed from you on this page.',
  'cost.month.limit': 'Monthly limit',
  'cost.month.notSet': 'Not set',
