  'monitoring.title': 'Monitoring',
  'monitoring.purpose': 'What can stop without anyone noticing.',
  'monitoring.about': 'What can stop without anyone noticing: background jobs, delivery notices, messages that did not go, held replies, the nightly work and templates.',
  'monitoring.summary.clear': 'Nothing here needs a look right now.',
  'monitoring.summary.look.one': '{count} section needs a look.',
  'monitoring.summary.look.other': '{count} sections need a look.',
  'monitoring.privacy': 'Counts, ages and school names only: no parent’s or child’s name, no phone number and no words of a message are shown here. An error text is shown only after anything that looks like a phone number or an email address is cut out.',
  'monitoring.readAt': 'Read at {when}, India time. Reload the page for the latest.',
