  'aud.check.guardian_phone.rule': 'A guardian is counted when their number is not one WhatsApp can use: a ten-digit mobile number starting 6 to 9, with or without 91 before it, or another country’s number written with + and its code.',
  'aud.check.guardian_phone.where': 'the guardians listed on Parents.',
