  'tour.curriculum-gap.1.text': 'Every unit of its syllabus map is listed once, in the map’s order. Without a map the page says it is not set up.',
  'tour.curriculum-gap.2.title': 'Each unit has one state',
  'tour.curriculum-gap.2.text': 'Taught and assessed, taught but not assessed, assessed before it was taught, skipped, or not taught yet, with the days it rests on.',
