  // Learning Genome v1 (docs/27 row 9e, C217): one child's own exams, homework and Pulse replies, for staff only.
  'moduleOff.learning-genome': '“Learning Genome” leaves the menu and nobody can open a child’s genome. It stores nothing, so nothing is lost: marks, homework and replies stay where they are.',
  'tour.learning-genome.1.title': 'Pick a class, then a child',
  'tour.learning-genome.1.text': 'A teacher sees the children of their own classes. The office and the academic coordinator see every class.',
  'tour.learning-genome.2.title': 'Compared only with themselves',
  'tour.learning-genome.2.text': 'Strengths and gaps hold the child against their own earlier exam, their own overall and their own replies. Never another child.',
  'tour.learning-genome.3.title': 'Every number says where it is from',
  'tour.learning-genome.3.text': 'A percent shows its marks, homework its checks, a chapter the replies it counts, and each rule the line set in Settings.',
  'set.learning-genome.trend_points.label': 'A subject rising or falling by at least this many points',
  'set.learning-genome.trend_points.help': 'A subject is a strength when the child’s percent rose by at least this many points against their own previous exam in it, and a gap when it fell by as many, from 1 to 50.',
  'set.learning-genome.spread_points.label': 'A subject above or below their own overall by at least this many points',
  'set.learning-genome.spread_points.help': 'In the child’s latest exam with two subjects or more, a subject this many points above their own overall in that exam is a strength, and as many below is a gap, from 1 to 50.',
  'set.learning-genome.needs_help_replies.label': 'A chapter with at least this many “needs help” replies',
  'set.learning-genome.needs_help_replies.help': 'A chapter is a gap when the child’s parents replied “needs help” to the Daily Pulse of its taught lessons at least this many times in the days looked back, from 1 to 20.',
  'set.learning-genome.understood_replies.label': 'A chapter with at least this many “understood” replies',
  'set.learning-genome.understood_replies.help': 'A chapter is a strength when the parents replied “understood” at least this many times and never “needs help”, from 1 to 20.',
  'set.learning-genome.homework_done_below.label': 'Homework done on fewer than this many in every 100',
  'set.learning-genome.homework_done_below.help': 'Homework in a subject is a gap when the child did fewer than this many of every 100 homeworks checked in the days looked back, from 1 to 100.',
  'set.learning-genome.homework_min_checked.label': 'Only when at least this many homeworks were checked',
  'set.learning-genome.homework_min_checked.help': 'Homework is not used until at least this many of the child’s homeworks in the subject were checked, from 1 to 50. With fewer, one missed homework would look larger than it is.',
  'set.learning-genome.window_days.label': 'Homework and replies over this many days back',
  'set.learning-genome.window_days.help': 'How many days back homework and Daily Pulse replies are counted, today included, from 7 to 366. Exams are counted from the first one published.',
